  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 Writing a Business Plan$j$, $j${"readings": [{"title": "Habakkuk 2 (King James Version)", "url": "/portal/bible/Habakkuk/2"}], "body": "A business plan is a written guide that describes your business and how it will succeed. Habakkuk 2:2 says, Write the vision, and make it plain upon tables, that he may run that readeth it. A plan helps you think clearly and helps others understand and support you.\n\nA standard business plan has these parts. The executive summary is a short overview written last but placed first. The company description gives the name, structure, mission and values. The market analysis describes the target market, customer needs and competitors. The products or services section explains what you offer and the value proposition. The marketing and sales plan covers the four Ps and how you will reach customers. The operations plan covers location, suppliers, equipment, people and daily process. The management and team section describes who is responsible. The financial plan includes startup costs, a budget, a break even analysis, a sales forecast and a cash flow plan. The risks and giving plan covers what could go wrong, how you will respond and how you will bless others.\n\nGood plans are clear, honest, realistic and brief. Use simple language, back up claims with research and show your math. Do not invent numbers to look impressive. A forecast is a reasoned estimate, not a promise. Use cautious, middle and best case numbers.\n\nKeep the plan alive. Review it every few months and update it as you learn. Proverbs 16:3 says, Commit thy works unto the LORD, and thy thoughts shall be established.\n\nYour task: (1) List the nine parts of a business plan. (2) Write the company description and market analysis for your idea. (3) Explain why honest numbers matter.\n\nFlorida standards: BE.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "BE.912", "script": "Welcome back. Listen, Habakkuk 2:2 says, Write the vision, and make it plain upon tables, that he may run that readeth it. Proverbs 16:3 says, Commit thy works unto the LORD, and thy thoughts shall be established.\n\nNow watch this. A business plan is a written guide to your business. The parts are the executive summary, company description, market analysis, products and services, marketing and sales, operations, management and team, financial plan, and risks and giving.\n\nWrite the executive summary last but place it first. Keep language simple, back up claims with research and show your math. A forecast is a reasoned estimate, not a promise. Use cautious, middle and best case numbers, and never invent numbers to look impressive.\n\nReview and update the plan every few months.\n\nYour task is to list the parts, write two sections and explain honest numbers. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 Writing a Business Plan$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 Building the Financial Plan$j$, $j${"readings": [{"title": "Proverbs 24 (King James Version)", "url": "/portal/bible/Proverbs/24"}], "body": "The financial section turns your ideas into numbers. Proverbs 24:27 says, Prepare thy work without, and make it fit for thyself in the field; and afterwards build thine house. Count first, then build.\n\nBegin with startup costs: list every one time cost and add a cushion of ten to twenty percent. Next, create a sales forecast. Estimate how many units you expect to sell each month and at what price. Use research, such as your customer interviews and competitor prices, not hopes alone. Multiply units by price to find expected revenue. Then list monthly costs: variable costs per unit, fixed costs and taxes set aside.\n\nExample. A student plans to sell tutoring sessions for 20 dollars each. Materials and travel cost 2 dollars per session. Fixed costs are 90 dollars a month for a simple website and supplies. The contribution margin is 18 dollars per session. The break even point is 90 divided by 18, which is 5 sessions per month. If the student expects 20 sessions, revenue is 400 dollars, variable costs are 40 dollars, fixed costs are 90 dollars and profit is 270 dollars before taxes and giving.\n\nAdd a cash flow plan that shows when money comes in and goes out each month. Include a reserve and a plan for taxes. Test your assumptions by asking what happens if sales are 25 percent lower or costs are 10 percent higher. This is called a sensitivity check, and it prepares you for surprises.\n\nDo not include real bank account numbers, Social Security numbers or other private details in any plan you share. Use sample figures for practice.\n\nYour task: (1) Complete a break even example with your own numbers. (2) Create a six month forecast. (3) Run a sensitivity check.\n\nFlorida standards: BE.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "BE.912", "script": "Welcome back. Listen, Proverbs 24:27 says, Prepare thy work without, and make it fit for thyself in the field; and afterwards build thine house. Count first, then build.\n\nNow watch this. Begin with startup costs and add a cushion of ten to twenty percent. Then forecast sales using research, not hope. Units times price gives expected revenue. List variable costs, fixed costs and taxes.\n\nExample. Tutoring sells at 20 dollars. Variable cost is 2 dollars, so the margin is 18 dollars. Fixed costs are 90 dollars a month. Break even is 90 divided by 18, which is 5 sessions. With 20 sessions, revenue is 400 dollars, variable costs 40, fixed costs 90, and profit 270 dollars before taxes and giving.\n\nAdd a cash flow plan and a reserve. Run a sensitivity check: what if sales are 25 percent lower or costs 10 percent higher?\n\nNever include real bank numbers, Social Security numbers or private details in a plan. Use sample figures.\n\nYour task is to complete a break even example, a forecast and a sensitivity check. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 Building the Financial Plan$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 Pitching Your Business$j$, $j${"readings": [{"title": "Proverbs 25 (King James Version)", "url": "/portal/bible/Proverbs/25"}], "body": "A pitch is a short, clear presentation that explains your business and invites support. Proverbs 25:11 says, A word fitly spoken is like apples of gold in pictures of silver. Prepare what you will say.\n\nA good pitch answers six questions. What problem do you solve? Who is the customer? What is your solution and value proposition? How will you make money? What do you need, such as advice, a customer, a partner or funding? Why are you the right person or team? Start with a hook, a sentence or story that captures attention. Keep it to two or three minutes, use simple words and speak with confidence and humility.\n\nUse visual aids carefully. A short slide deck or a one page summary with clear headings and few words is enough. Show your numbers briefly. Practice aloud, time yourself and ask a trusted adult for feedback. Make eye contact, stand up straight, and breathe. Welcome questions, answer honestly, and say I will find out when you do not know. Never exaggerate to win support.\n\nBe careful with investors and offers. Real funding involves legal agreements, ownership and repayment. A student must not sign anything or accept money without a parent or guardian and, where needed, an attorney. Be wary of anyone who asks for money up front, promises large returns or pressures you to decide quickly.\n\nAfter the pitch, thank the listeners, follow up in writing and apply the feedback. Proverbs 12:15 says, he that hearkeneth unto counsel is wise.\n\nYour task: (1) Write a two minute pitch for your idea. (2) List three questions an audience might ask and your answers. (3) Describe two warning signs of a bad funding offer.\n\nFlorida standards: BE.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "BE.912", "script": "Welcome back. Listen, Proverbs 25:11 says, A word fitly spoken is like apples of gold in pictures of silver. Prepare what you will say.\n\nNow watch this. A pitch is a short, clear presentation. It answers six questions: what problem, who is the customer, what is the solution and value, how do you make money, what do you need and why are you the right person.\n\nStart with a hook. Keep it to two or three minutes. Use simple words, speak with confidence and humility, and never exaggerate. Use a short slide deck or one page summary. Practice aloud and ask an adult for feedback.\n\nBe careful with funding offers. A student must not sign anything or accept money without a parent or guardian and an attorney when needed. Beware anyone who asks for money up front, promises large returns or pressures you.\n\nAfterward, thank the listeners and follow up. Proverbs 12:15 says, he that hearkeneth unto counsel is wise.\n\nYour task is to write a pitch, answer three questions and name two warning signs. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 Pitching Your Business$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Launch, Review and Lifelong Stewardship$j$, $j${"readings": [{"title": "Matthew 25 (King James Version)", "url": "/portal/bible/Matthew/25"}], "body": "Launching is the moment a plan becomes action. Proverbs 16:9 says, A man's heart deviseth his way: but the LORD directeth his steps. Plan carefully, pray and then take faithful steps.\n\nA launch checklist includes confirming that you have adult support and approval, registering and licensing where required, setting up a safe way to take payments, preparing your price list and policies, testing your product or service with a few trusted customers, preparing your marketing, and organizing records and a budget. Start small. A pilot is a small scale test that lets you learn before you invest more. Collect feedback, fix problems and improve.\n\nAfter launch, review your results often. Compare actual numbers to the plan. Ask what worked, what did not and what to change. Use measures such as revenue, profit, customers, repeat customers, complaints and time spent. Make decisions with facts, not feelings alone. Keep learning from books, mentors and other business owners. Seek counsel from godly, experienced people, as Proverbs 11:14 says, in the multitude of counsellors there is safety.\n\nKeep your priorities in order. Your relationship with God, family, health, school and rest come before profit. Colossians 3:17 says, whatsoever ye do in word or deed, do all in the name of the Lord Jesus. Entrepreneurship is not only about making money. It is about serving people, solving problems, creating opportunity and giving glory to God.\n\nRemember the parable of the talents in Matthew 25:14 to 30. The master praised the servants who used their talents faithfully and rebuked the one who hid his. Whatever you have, use it well. Whether you start a business, become a leader inside a company or serve in ministry, be a faithful steward.\n\nYour task: (1) Create a launch checklist for your idea. (2) Describe how you will review results every month. (3) Explain the lesson of the talents for your future.\n\nFlorida standards: BE.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "BE.912", "script": "Welcome back. Listen, Proverbs 16:9 says, A man's heart deviseth his way: but the LORD directeth his steps. Plan carefully, pray and take faithful steps.\n\nNow watch this. A launch checklist includes adult support and approval, required registration and licenses, a safe way to take payments, a price list and policies, a test with trusted customers, marketing and organized records. Start small with a pilot, then collect feedback and improve.\n\nAfter launch, compare actual numbers to the plan. Track revenue, profit, customers, repeat customers and complaints. Decide with facts. Seek godly counsel. Proverbs 11:14 says, in the multitude of counsellors there is safety.\n\nKeep your priorities in order. God, family, health, school and rest come before profit. Colossians 3:17 says, whatsoever ye do in word or deed, do all in the name of the Lord Jesus.\n\nIn Matthew 25, the master praised the servants who used their talents faithfully. Be a faithful steward.\n\nYour task is to create a launch checklist, plan monthly reviews and explain the talents. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Launch, Review and Lifelong Stewardship$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: The Business Plan, Pitch and Launch$j$, $j${"prompt": "Write a report of at least 250 words. Use complete sentences and label each part. Habakkuk 2:2 says, Write the vision, and make it plain upon tables, that he may run that readeth it.\n\nPart 1: List and explain the nine parts of a business plan and explain why an executive summary is written last.\nPart 2: Using sample figures only, compute a break even point, a monthly profit and a sensitivity check for a business idea. Show your work.\nPart 3: Write a two minute pitch that answers the six pitch questions and name two warning signs of a bad funding offer.\nPart 4: Create a launch checklist, a pilot plan and a monthly review plan.\nPart 5: Explain Matthew 25:14 to 30, Proverbs 16:9 and Colossians 3:17, and tell how you will be a faithful steward.", "rubric": "100 points. Part 1: 20 points. Part 2: 25 points. Part 3: 20 points. Part 4: 15 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: The Business Plan, Pitch and Launch$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: Faithful Stewards of Every Talent$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a talent or skill God has given you and how it could serve others, (2) explains the first three steps you would take to test an idea with a small pilot, (3) explains why priorities such as faith, family and rest must come before profit, and (4) connects your answer to Matthew 25:14 to 30, Proverbs 16:9 or Colossians 3:17. Then write a respectful reply of at least 40 words to another student's post, or answer this question: What does it mean to be a faithful steward in business? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: Faithful Stewards of Every Talent$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: Writing a Business Plan$j$, $j${"questions": [{"q": "Habakkuk 2:2 teaches us to:", "options": ["Write the vision and make it plain", "Hide the plan", "Avoid writing", "Copy others"]}, {"q": "The executive summary is:", "options": ["A contract", "A short overview placed first and written last", "The tax form", "A price list"]}, {"q": "A forecast is:", "options": ["A tax", "A loan", "A guarantee", "A reasoned estimate, not a promise"]}, {"q": "A financial plan includes:", "options": ["Startup costs, budget and break even analysis", "Only a name", "Only a slogan", "Only a logo"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Writing a Business Plan$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,3,0}'::int[], array[$j$Written plans bring clarity.$j$,$j$It summarizes the whole plan.$j$,$j$Forecasts estimate the future.$j$,$j$Numbers prove the plan is realistic.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Writing a Business Plan$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: Building the Financial Plan$j$, $j${"questions": [{"q": "Tutoring at 20 dollars with a 2 dollar variable cost and 90 dollars fixed costs breaks even at:", "options": ["9 sessions", "90 sessions", "45 sessions", "5 sessions"]}, {"q": "Revenue equals:", "options": ["Costs times units", "Units times price", "Price minus units", "Units plus price"]}, {"q": "A sensitivity check asks:", "options": ["What your name is", "What happens if sales or costs change", "Where you live", "Who your friends are"]}, {"q": "In a shared plan you should not include:", "options": ["Your price list", "Sample figures", "Real bank account numbers", "Your mission"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Building the Financial Plan$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,1,2}'::int[], array[$j$Margin 18 and 90 divided by 18 is 5.$j$,$j$Multiply the quantity sold by the price.$j$,$j$It tests assumptions.$j$,$j$Keep private details out.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Building the Financial Plan$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Pitching Your Business$j$, $j${"questions": [{"q": "A pitch should be about:", "options": ["Two or three minutes", "Two hours", "Ten seconds", "One word"]}, {"q": "A warning sign of a bad funding offer is:", "options": ["A written agreement reviewed by adults", "Time to think", "Promises of large returns and pressure to decide fast", "Clear terms"]}, {"q": "A hook is:", "options": ["A price", "A loan", "A sentence or story that captures attention", "A tax form"]}, {"q": "When you do not know an answer in a pitch, you should:", "options": ["Argue", "Say you will find out", "Leave the room", "Invent one"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Pitching Your Business$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,2,1}'::int[], array[$j$Short and clear works best.$j$,$j$Pressure and big promises signal danger.$j$,$j$Hooks open the pitch.$j$,$j$Honesty protects trust.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Pitching Your Business$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Launch, Review and Lifelong Stewardship$j$, $j${"questions": [{"q": "A pilot is:", "options": ["A small scale test before investing more", "A tax", "A type of loan", "A company name"]}, {"q": "Proverbs 16:9 says the LORD:", "options": ["Ends plans", "Charges interest", "Directeth his steps", "Hides from us"]}, {"q": "After launch you should:", "options": ["Compare actual results to the plan", "Hide records", "Stop tracking", "Avoid feedback"]}, {"q": "In the parable of the talents the master praised servants who were:", "options": ["Careless", "Hidden", "Fearful", "Faithful with what they had"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Launch, Review and Lifelong Stewardship$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,0,3}'::int[], array[$j$Pilots reduce risk.$j$,$j$God guides faithful planners.$j$,$j$Review leads to improvement.$j$,$j$Faithful stewardship is rewarded.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Launch, Review and Lifelong Stewardship$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: The Business Plan, Pitch and Launch$j$, $j${"questions": [{"q": "A business plan is:", "options": ["A product", "A loan", "A tax form", "A written guide to the business"]}, {"q": "The executive summary is written:", "options": ["Last", "Never", "By a competitor", "First always"]}, {"q": "A tutoring service charges 25 dollars with a 5 dollar variable cost and 100 dollars fixed costs. Break even is:", "options": ["4 sessions", "20 sessions", "5 sessions", "10 sessions"]}, {"q": "A sensitivity check tests:", "options": ["Assumptions if conditions change", "Your name", "Your logo", "Your age"]}, {"q": "A good pitch is:", "options": ["Exaggerated", "Long and confusing", "Secret", "Short, clear and honest"]}, {"q": "A student accepting funding should involve:", "options": ["No one", "A friend online alone", "Only strangers", "A parent or guardian"]}, {"q": "Starting with a small test is called a:", "options": ["Merger", "Pilot", "Audit", "Default"]}, {"q": "Proverbs 11:14 says in the multitude of counsellors there is:", "options": ["Fame", "Confusion", "Debt", "Safety"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: The Business Plan, Pitch and Launch$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,2,0,3,3,1,3}'::int[], array[$j$Plans clarify direction.$j$,$j$It summarizes the finished plan.$j$,$j$Margin 20 and 100 divided by 20 is 5.$j$,$j$It prepares you for surprises.$j$,$j$Honesty and clarity win trust.$j$,$j$Adults must be involved.$j$,$j$Pilots reduce risk.$j$,$j$Seek wise counsel.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: The Business Plan, Pitch and Launch$j$ on conflict (item_id) do nothing;
